<div class="page-heading"><div><span class="eyebrow">TEAM SPENDING</span><h1>Approvals</h1><p><?= count($entries) ?> expenses waiting for your review.</p></div></div>
<div class="table-wrap"><table><thead><tr><th>Expense</th><th>Submitted by</th><th>Category</th><th class="number">Amount</th><th>Review</th></tr></thead><tbody><?php foreach($entries as $row): ?><tr><td><a class="strong" href="<?= e(url('entry',['id'=>$row['id']])) ?>"><?= e($row['description']) ?></a><small class="block muted"><?= short_date($row['entry_date']) ?></small></td><td><?= e($row['author']) ?></td><td><?= e($row['category']??'Uncategorized') ?></td><td class="number strong"><?= money($row['amount']) ?></td><td><div class="inline-form"><a class="button small" href="<?= e(url('entry',['id'=>$row['id']])) ?>">Review</a><form method="post" action="<?= e(url('entry-action')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $row['id'] ?>"><button class="icon-button positive" name="action" value="approve" title="Approve expense" aria-label="Approve <?= e($row['description']) ?>"><?= icon('check') ?></button></form></div></td></tr><?php endforeach ?><?php if(!$entries): ?><tr><td colspan="5"><div class="empty-state"><?= icon('circle-check') ?><h3>All caught up</h3><p>No expenses are waiting for approval.</p></div></td></tr><?php endif ?></tbody></table></div>
